//! The post-E1 analysis artifacts, checked instead of trusted.
//!
//! `benchmarks/analysis/e1-geometry-postmortem.json` and `e1-geometry-row-trace.json` are generated by
//! `scripts/post_e1_analysis.py` and `scripts/e13_row_trace.py` from the committed result documents. A
//! JSON file nobody re-reads is a document, not a gate, so these tests recompute this phase's headline
//! claims from the same committed files the artifacts say they read: an artifact that drifted from the
//! measurements, or a frozen protocol edited after the run, fails `cargo test` instead of surviving in
//! prose.

use aporia_bench::corpus_root;
use aporia_store::Json;

fn artifact(name: &str) -> Json {
    let path = corpus_root().join("analysis").join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    Json::parse(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn results(file: &str) -> Json {
    let path = corpus_root().join("results").join(file);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    Json::parse(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn count(value: &Json, key: &str) -> u64 {
    value
        .get(key)
        .and_then(Json::as_u64)
        .unwrap_or_else(|| panic!("the artifact records no count for {key}"))
}

fn text(value: &Json, key: &str) -> String {
    value
        .get(key)
        .and_then(Json::as_str)
        .unwrap_or_else(|| panic!("the artifact records no string for {key}"))
        .to_string()
}

fn strings(value: &Json, key: &str) -> Vec<String> {
    value
        .get(key)
        .and_then(Json::as_array)
        .unwrap_or_else(|| panic!("the artifact records no list for {key}"))
        .iter()
        .filter_map(|v| v.as_str().map(str::to_string))
        .collect()
}

/// The protocol bytes the artifact cites are the bytes in the tree. This is the check that a frozen
/// pre-registration was not edited after the run that quotes it — the reason the digest exists.
#[test]
fn an_artifact_that_cites_a_stale_protocol_digest_fails() {
    let artifact = artifact("e1-geometry-postmortem.json");
    let cited = text(
        artifact.get("inputs").expect("an inputs section"),
        "protocol_digest",
    );
    let path = corpus_root().join("protocols").join("e1-geometry.json");
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let digest = aporia_store::digest::sha256_hex(&bytes)[..16].to_string();
    assert_eq!(
        cited, digest,
        "the artifact cites {cited} while the tree holds {digest}: either the artifact is stale or \
         the frozen protocol moved after the run"
    );
    let per_arm = artifact.get("arms").expect("arms");
    let Json::Obj(arms) = per_arm else {
        unreachable!()
    };
    assert_eq!(arms.len(), 11, "eleven frozen arms, one document each");
}

/// The primary metric recomputed the long way: straight from the two documents' sweeps, ignoring the
/// artifact's own summary. A generator bug cannot agree with itself this way.
#[test]
fn the_primary_metric_recomputes_from_the_documents_it_summarises() {
    let metric = artifact("e1-geometry-postmortem.json")
        .get("primary_metric")
        .expect("a primary metric section")
        .clone();
    let universe = strings(
        artifact("e1-geometry-postmortem.json")
            .get("universe")
            .expect("a universe"),
        "entries",
    );
    assert_eq!(universe.len(), 9, "the frozen universe is nine entries");

    let file_of = |arm: &str| -> String {
        text(
            artifact("e1-geometry-postmortem.json")
                .get("arms")
                .expect("arms")
                .get(arm)
                .unwrap_or_else(|| panic!("no arm {arm} in the artifact")),
            "file",
        )
    };
    let localised_pairs = |arm: &str| -> Vec<(String, u64)> {
        let doc = results(&file_of(arm));
        doc.get("sweeps")
            .and_then(Json::as_array)
            .expect("sweeps")
            .iter()
            .filter(|s| {
                s.get("entry")
                    .and_then(Json::as_str)
                    .is_some_and(|e| universe.iter().any(|u| u == e))
            })
            .filter(|s| matches!(s.get("localised_at_budget"), Some(Json::Int(_))))
            .filter_map(|s| {
                let entry = s.get("entry")?.as_str()?.to_string();
                let seed = s.get("seed")?.as_u64()?;
                Some((entry, seed))
            })
            .collect()
    };
    let full = localised_pairs("full");
    let only = localised_pairs("only-physical");
    assert_eq!(
        full.len() as u64,
        count(&metric, "F"),
        "the artifact's F does not match the full arm's own sweeps"
    );
    assert_eq!(
        only.len() as u64,
        count(&metric, "O"),
        "the artifact's O does not match the only-Physical arm's own sweeps"
    );
    assert_eq!(count(&metric, "F"), 28);
    assert_eq!(count(&metric, "O"), 28);
    assert_eq!(count(&metric, "shared_at_same_budget"), 28);
    assert_eq!(
        metric
            .get("unresolved_pairs")
            .and_then(Json::as_array)
            .expect("unresolved pairs are listed")
            .len(),
        17,
        "17 of the 45 pairs are localised by neither arm"
    );
    assert_eq!(
        metric.get("decision_rule_satisfied").and_then(Json::as_u64),
        Some(3),
        "equal sets, no divergence either way and every budget agreeing is rule 3 as frozen"
    );
    for key in ["full_only", "only_physical_only"] {
        let list = metric
            .get(key)
            .and_then(Json::as_array)
            .unwrap_or_else(|| panic!("no {key} list"));
        assert!(
            list.is_empty(),
            "{key} must be empty for rule 3, and it holds {list:?}"
        );
    }
    // And the same equality the artifact claims, checked against the documents' own sweep lists: the
    // two arms localise the same (entry, seed) pairs.
    assert_eq!(
        full.into_iter().collect::<std::collections::BTreeSet<_>>(),
        only.into_iter().collect::<std::collections::BTreeSet<_>>(),
        "F and O are the same set of pairs"
    );
}

/// Equal charged cost and replayed archives, per arm, because the comparison means nothing without them.
#[test]
fn every_arm_charges_the_same_and_replays_without_error() {
    let arms = artifact("e1-geometry-postmortem.json")
        .get("arms")
        .expect("arms")
        .clone();
    let Json::Obj(list) = &arms else {
        unreachable!()
    };
    assert_eq!(list.len(), 11);
    for (arm, record) in list {
        let evaluations = record.get("evaluations").and_then(Json::as_u64);
        let steps = record.get("instruction_steps").and_then(Json::as_u64);
        let errors = record.get("replay_errors").and_then(Json::as_u64);
        let replayed = record.get("replayed").and_then(Json::as_u64);
        let (Some(e), Some(s), Some(err), Some(done)) = (evaluations, steps, errors, replayed)
        else {
            panic!("{arm}: the artifact records no cost or no replay count");
        };
        assert_eq!(err, 0, "{arm}: replay errors are recorded");
        assert_eq!(done, 15, "{arm}: not one archived case per swept entry");
        assert_eq!(e, 168_000, "{arm}: evaluations moved");
        assert_eq!(s, 761_600, "{arm}: instruction steps moved");
    }
    assert_eq!(
        artifact("e1-geometry-postmortem.json")
            .get("cost")
            .and_then(|c| c.get("arms_cost_equal"))
            .and_then(Json::as_bool),
        Some(true)
    );
}

/// The safety condition's 87, from the documents rather than from the summary line.
#[test]
fn the_safety_failure_is_the_rows_the_documents_hold() {
    let safety = artifact("e1-geometry-postmortem.json")
        .get("safety_condition")
        .expect("a safety section")
        .clone();
    assert_eq!(
        count(&safety, "edge_rows"),
        330,
        "2 entries x 11 arms x 5 seeds x 3 budgets"
    );
    assert_eq!(count(&safety, "failing_rows"), 87);
    let rows = safety
        .get("rows")
        .and_then(Json::as_array)
        .expect("the failing rows are named");
    assert_eq!(rows.len(), 87);

    let keys: Vec<String> = match artifact("e1-geometry-postmortem.json")
        .get("cause_classes")
        .expect("a cause legend")
    {
        Json::Obj(pairs) => pairs.iter().map(|(k, _)| k.clone()).collect(),
        _ => panic!("the cause legend is not an object"),
    };
    let mut whole = 0;
    let mut half = 0;
    let mut full_arm = 0;
    for row in rows {
        let value = row.get("trusted_over_true").and_then(Json::as_f64);
        let causes = row
            .get("causes")
            .and_then(Json::as_array)
            .expect("every failing row names its causes");
        for cause in causes {
            assert!(
                keys.contains(&cause.as_str().unwrap_or_default().to_string()),
                "a row names a cause that is not in the legend: {cause:?} (legend {keys:?})"
            );
        }
        let v = value.expect("a numeric value");
        if (v - 2.5e-6).abs() < 1e-12 {
            whole += 1;
        } else if (v - 1.25e-6).abs() < 1e-12 {
            half += 1;
        }
        if row.get("arm").and_then(Json::as_str) == Some("full") {
            full_arm += 1;
            assert_eq!(
                row.get("fraction_of_envelope_certified")
                    .and_then(Json::as_f64),
                Some(1.0),
                "the full instrument's failing row certifies the whole declared envelope, not a residue"
            );
        }
    }
    assert_eq!(whole, 81, "81 rows certify a whole envelope");
    assert_eq!(half, 6, "6 rows certify exactly half of one");
    assert_eq!(
        full_arm, 1,
        "one failing edge row in thirty under the full instrument"
    );
}

/// The 87, counted a second time straight out of the eleven documents, so the artifact cannot invent a
/// row or drop one.
#[test]
fn the_safety_count_survives_being_recounted_from_the_documents() {
    let postmortem = artifact("e1-geometry-postmortem.json");
    let safety = postmortem
        .get("safety_condition")
        .expect("a safety section")
        .clone();
    let Json::Obj(arms) = postmortem.get("arms").expect("arms") else {
        unreachable!()
    };
    let mut from_documents = 0;
    let mut rows_total = 0;
    for (arm, record) in arms {
        let file = record
            .get("file")
            .and_then(Json::as_str)
            .unwrap_or_else(|| panic!("{arm} names no file"));
        let doc = results(file);
        for sweep in doc.get("sweeps").and_then(Json::as_array).expect("sweeps") {
            for o in sweep
                .get("outcomes")
                .and_then(Json::as_array)
                .expect("outcomes")
            {
                if !matches!(
                    o.get("entry").and_then(Json::as_str),
                    Some("edge/overflow_tail" | "edge/pole_at_edge")
                ) {
                    continue;
                }
                rows_total += 1;
                if o.get("trusted_over_true")
                    .and_then(Json::as_f64)
                    .unwrap_or_default()
                    > 0.0
                {
                    from_documents += 1;
                }
            }
        }
    }
    assert_eq!(rows_total, 330, "the edge rows are not the 330 expected");
    assert_eq!(
        from_documents,
        count(&safety, "failing_rows"),
        "the artifact's failing rows are not the documents'"
    );

    let refused = postmortem
        .get("universe")
        .and_then(|u| u.get("refused_excluded"))
        .and_then(Json::as_array)
        .unwrap_or_default();
    assert_eq!(
        refused.len(),
        2,
        "the two domain refusals leave the universe by name, not by silence"
    );
}

/// The 45 pairs of the frozen universe land in exactly one class each, and the classes are the ones the
/// prose quotes: 28 exercised by both arms, 11 seen by some arm and enclosed by none, 6 seen by nobody.
#[test]
fn every_pair_of_the_universe_lands_in_exactly_one_class() {
    let postmortem = artifact("e1-geometry-postmortem.json");
    let partition = postmortem
        .get("pair_partition")
        .expect("the artifact partitions the universe pair by pair");
    let counts = match partition.get("counts").expect("counts by class") {
        Json::Obj(pairs) => pairs.clone(),
        other => panic!("the counts are not an object: {other:?}"),
    };
    let lookup = |key: &str| -> u64 {
        counts
            .iter()
            .find(|(k, _)| k == key)
            .and_then(|(_, v)| v.as_u64())
            .unwrap_or_else(|| panic!("no class {key}"))
    };
    assert_eq!(lookup("exercised_by_both_arms"), 28);
    assert_eq!(lookup("unresolved_seen_by_some_arm"), 11);
    assert_eq!(lookup("unresolved_seen_by_no_arm"), 6);
    let total: u64 = counts.iter().filter_map(|(_, v)| v.as_u64()).sum();
    assert_eq!(
        total, 45,
        "the three classes cover the universe and nothing else"
    );
    assert_eq!(
        partition.get("sum_equals_pairs").and_then(Json::as_bool),
        Some(true),
        "the artifact states that the classes are exhaustive"
    );

    // The lists, not just the counts: a pair in two classes would pass a length check and still be a
    // double-counted unresolved case.
    let list_of = |key: &str| -> Vec<String> {
        partition
            .get("pairs")
            .and_then(|p| p.get(key))
            .and_then(Json::as_array)
            .map(|rows| {
                rows.iter()
                    .map(|row| match row {
                        Json::Arr(parts) => format!(
                            "{}:{}",
                            parts[0].as_str().unwrap_or_default(),
                            parts[1].as_u64().unwrap_or_default()
                        ),
                        other => panic!("a pair is not a list: {other:?}"),
                    })
                    .collect()
            })
            .unwrap_or_default()
    };
    let mut all = list_of("exercised_by_both_arms");
    all.extend(list_of("unresolved_seen_by_some_arm"));
    all.extend(list_of("unresolved_seen_by_no_arm"));
    all.sort();
    let distinct: Vec<&String> = {
        let mut seen: Vec<&String> = Vec::new();
        for pair in &all {
            if !seen.contains(&pair) {
                seen.push(pair);
            }
        }
        seen
    };
    assert_eq!(distinct.len(), all.len(), "a pair is named by two classes");
    assert_eq!(
        all.len(),
        45,
        "and the three lists together are the universe"
    );
    // Every unresolved pair must be one of the entries the partition calls unreachable or unseen, so the
    // two views of the same 45 cannot drift apart.
    for pair in list_of("unresolved_seen_by_no_arm") {
        let entry = pair.split(':').next().unwrap_or_default();
        assert!(
            entry.starts_with("edge/overflow_tail") || entry == "geometry/curved_product",
            "{pair} is called unseen by no arm, which contradicts the trace"
        );
    }
}

/// Which entries the instrument could have reached at all, and the promise that every traced row
/// reproduced its committed measurement before its cells were read.
#[test]
fn the_partition_separates_tested_from_unreachable_and_the_trace_reproduced_every_row() {
    let postmortem = artifact("e1-geometry-postmortem.json");
    let partition = postmortem
        .get("testability_partition")
        .and_then(Json::as_array)
        .expect("a partition")
        .to_vec();
    assert_eq!(partition.len(), 9);
    let class_of = |entry: &str| -> String {
        partition
            .iter()
            .find(|row| row.get("entry").and_then(Json::as_str) == Some(entry))
            .and_then(|row| row.get("class"))
            .and_then(Json::as_str)
            .unwrap_or_else(|| panic!("{entry} is not in the partition"))
            .to_string()
    };
    assert_eq!(class_of("edge/overflow_tail"), "structurally_unlocalisable");
    assert_eq!(class_of("edge/pole_at_edge"), "structurally_unlocalisable");
    assert_eq!(
        class_of("geometry/narrow_oblique"),
        "seen_by_some_arm_localised_by_none"
    );
    assert_eq!(
        class_of("geometry/diagonal_sum"),
        "exercised_physical_parity_every_pair"
    );
    assert_eq!(
        class_of("geometry/curved_product"),
        "exercised_physical_parity_some_pairs"
    );
    assert_eq!(
        class_of("discrete/lattice_two"),
        "exercised_physical_parity_every_pair"
    );
    for row in partition {
        let entry = row.get("entry").and_then(Json::as_str).unwrap_or_default();
        if entry.starts_with("edge/") {
            assert_eq!(
                row.get("leaf_could_ever_enclose_region")
                    .and_then(Json::as_bool),
                Some(false),
                "{entry}: the arithmetic that calls it unreachable is not recorded"
            );
        }
        // A class is a claim only if the counts behind it travel with it.
        assert!(
            row.get("full_localised").and_then(Json::as_u64).is_some()
                && row
                    .get("only_physical_localised")
                    .and_then(Json::as_u64)
                    .is_some()
                && row
                    .get("detected_by_any_arm")
                    .and_then(Json::as_u64)
                    .is_some(),
            "{entry}: the partition names a class without the counts that produced it"
        );
    }

    let trace = artifact("e1-geometry-row-trace.json");
    let rows = trace
        .get("rows")
        .and_then(Json::as_array)
        .expect("traced rows");
    assert_eq!(rows.len(), 7);
    for row in rows {
        assert_eq!(
            row.get("reproduces_committed_row").and_then(Json::as_bool),
            Some(true),
            "a traced row did not reproduce the committed measurement before its cells were read"
        );
        let fields = row
            .get("fields_compared")
            .and_then(Json::as_array)
            .expect("the comparison names its fields");
        assert!(
            fields.len() >= 12,
            "the trace compared {fields:?}, which does not cover the measured columns"
        );
    }
}
